  "codebook": {
    "clarification": "Include as credit-claiming: (1) announcements of federal grants, appropriations, projects, disaster declarations, designations, or facilities benefiting the senator's state or constituents, especially with verbs like 'secured,' 'delivered,' 'announced,' 'won,' 'helped obtain,' or 'funds I requested'; (2) claims of authorship, sponsorship, or leadership for legislation that has at least advanced beyond introduction—e.g., an amendment adopted, a provision included in a package, committee or chamber passage, or enactment; (3) claims that the senator's letter, appeal, nomination, pressure, or oversight caused a favorable executive or agency decision (base decisions, waivers, purchases, appointments, recovered funds); (4) joint claims made with delegation or bipartisan colleagues, and claims about past achievements, which count equally.",
    "definition": "Credit-claiming occurs when a senator publicly asserts personal responsibility (alone or jointly with delegation colleagues) for causing the government to produce a desirable, concrete outcome valued by constituents or particular groups—most commonly securing federal funds, grants, projects, designations, or facilities for the state, winning adoption or passage of legislative provisions the senator authored, or prompting a favorable executive decision through the senator's intervention. The defining feature is a causal claim linking the senator's own actions to a government benefit that has occurred or is being delivered.",
    "negative_clarification": "Do not classify as credit-claiming: (1) pure position-taking—statements of opinion, criticism or praise of the administration or other actors, explanations of votes, or support/opposition for pending policy without claiming responsibility for an outcome; (2) introduction or cosponsorship of unpassed legislation presented as advocacy, with no claim of a delivered benefit; (3) requests, demands, or letters urging future action that has not yet occurred; (4) commemorations, condolences, congratulatory messages, award presentations, essay contests, and meeting or town-hall announcements (advertising); (5) crediting others (e.g., the President) or an entire party's policies rather than the senator personally; (6) 'welcoming' or 'applauding' decisions made by others without asserting a causal role. A passing mention of past support ('I have supported...') without claiming causation of a benefit is not sufficient.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Kennedy introduces and argues the merits of a stem cell/cloning bill that has not passed; advocacy of unpassed legislation is position-taking, not a claim to have delivered a benefit."
      },
      {
        "document_id": "918",
        "explanation": "Allard simply announces a town meeting and invites constituents; this is event advertising with no claim of responsibility for any governmental action or benefit."
      },
      {
        "document_id": "656",
        "explanation": "Kerry criticizes the administration's handling of the Dubai ports deal and port security generally; he takes a position and assigns blame rather than claiming credit for any outcome."
      }
    ],
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Baucus and Tester explicitly state they 'delivered on their promise to secure federal funding' of $12.5 million for specific Butte projects—an unmistakable claim of personal responsibility for federal dollars brought to the state."
      },
      {
        "document_id": "2627",
        "explanation": "Talent announces the Senate 'approved his request' for $1.5 million for a University of Missouri research center, directly tying his own action to an appropriation benefiting the state."
      },
      {
        "document_id": "2318",
        "explanation": "Even within a letter pressuring state officials, Durbin claims 'I helped secure an expedited environmental review' and 'facilitated' the project's return to the federal funding priority list—asserting personal causation of favorable federal actions."
      }
    ]
  }
}
